    <style>
        :root {
            --q-color: #2e6db5;
            --hw-color: #d32f2f;
            --text-color: #333;
        }
        body {
            font-family: "PingFang SC", "Microsoft YaHei", sans-serif;
            background-color: #f0f0f0;
            margin: 0;
            padding: 20px;
            color: var(--text-color);
        }
        .page-container {
            background-color: white;
            max-width: 900px;
            margin: 0 auto;
            padding: 40px;
            box-shadow: 0 0 10px rgba(0,0,0,0.1);
            position: relative;
        }
        /* Header */
        .header {
            display: flex;
            justify-content: space-between;
            align-items: center;
            border-bottom: 2px solid #ccc;
            padding-bottom: 10px;
            font-size: 0.9em;
            color: #666;
            margin-bottom: 30px;
        }
        .header-left {
            display: flex;
            align-items: center;
            gap: 5px;
